name: Codex Review - Notify Code Owner

on:
  pull_request:
    types: [opened, synchronize, reopened, ready_for_review]
    branches:
      - main
      - develop
      - epic

permissions:
  contents: read
  pull-requests: write

jobs:
  notify-code-owner:
    if: github.event.pull_request.draft == false
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Get code owners
        id: codeowners
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const path = require('path');

            // Read CODEOWNERS file
            const codeownersPath = '.github/CODEOWNERS';
            let codeownersContent = '';

            try {
              codeownersContent = fs.readFileSync(codeownersPath, 'utf8');
            } catch (error) {
              console.log(`Could not read ${codeownersPath}: ${error.message}`);
              return { owners: [] };
            }

            // Parse CODEOWNERS entries
            const lines = codeownersContent.split('\n').filter(line => line.trim() !== '' && !line.startsWith('#'));
            const owners = new Set();

            for (const line of lines) {
              const parts = line.trim().split(/\s+/);
              if (parts.length > 1) {
                const filePathPattern = parts[0];
                const fileOwners = parts.slice(1);

                // Only consider direct file patterns (not directories or wildcards)
                if (!filePathPattern.includes('/') || filePathPattern.endsWith('/')) {
                  continue;
                }

                // Add owners to set
                for (const owner of fileOwners) {
                  if (owner.startsWith('@')) {
                    owners.add(owner.substring(1));
                  }
                }
              }
            }

            return { owners: Array.from(owners) };

      - name: Notify code owners
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owners } = require('./script.js');
            const prNumber = context.payload.pull_request.number;
            const prTitle = context.payload.pull_request.title;
            const prUrl = context.payload.pull_request.html_url;
            const author = context.payload.pull_request.user.login;

            // Create notification message
            const message = `@${owners.join(', @')} - Please review this pull request:\n\n**Title**: ${prTitle}\n**Author**: ${author}\n**URL**: ${prUrl}`;

            // Comment on PR
            await github.rest.issues.createComment({
              issue_number: prNumber,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: message
            });
```

